  "statements": [
    {
      "statement": "During normal operation, the HMMWV venting system allows vapor to escape to the atmosphere.",
      "reason": "The passage states this purpose under normal operation.",
      "verdict": 1,
      "evidence_ids": ["C001409"],
      "evidence_quotes": ["The purpose of\nthe vent system is to allow vapor to escape to the atmosphere under normal operation"]
    },
    {
      "statement": "During deep-water fording operations, the HMMWV vent system blocks venting.",
      "reason": "The passage says the vent system prevents venting during deep-water fording.",
      "verdict": 1,
      "evidence_ids": ["C001409"],
      "evidence_quotes": ["and to\nprevent venting during deep water fording operations."]
    },
    {
      "statement": "During deep-water fording operations, the HMMWV vent system prevents water from entering the engine.",
      "reason": "The passage says open vents during fording would let water enter the engine.",
      "verdict": 1,
      "evidence_ids": ["C001409"],
      "evidence_quotes": ["prevent venting during deep water fording operations. If the vents were left open, water would\nenter the engine and other systems and cause damage."]
    },
    {
      "statement": "During deep-water fording operations, the HMMWV vent system prevents water from entering other systems.",
      "reason": "The passage says open vents during fording would let water enter other systems.",
      "verdict": 1,
      "evidence_ids": ["C001409"],
      "evidence_quotes": ["prevent venting during deep water fording operations. If the vents were left open, water would\nenter the engine and other systems and cause damage."]
    },
    {
      "statement": "During deep-water fording operations, preventing water entry by blocking venting avoids damage.",
      "reason": "The passage links preventing venting during fording with avoiding the water entry and damage that open vents would cause.",
      "verdict": 1,
      "evidence_ids": ["C001409"],
      "evidence_quotes": ["prevent venting during deep water fording operations. If the vents were left open, water would\nenter the engine and other systems and cause damage."]
    }
  ]
}

